    function updateCounts(){for(const [selector,node] of [['[data-dt-input-count]',input],['[data-dt-secondary-count]',secondary]])$dt(selector).textContent=`${node.value.length.toLocaleString()} characters`;}
    function smartSuggestion(){const guess=smartDetect(input.value);detected=guess;$dt('[data-dt-detect]').textContent=guess?`Looks like ${GLITCHYARD_TOOL_MAP.get(guess)?.title||guess}. Use the suggestion to switch tools.`:'Paste or type something to get a tool suggestion.';$dt('[data-dt-suggest]').disabled=!guess||guess===selected;$dt('[data-dt-suggest]').textContent=guess?`Open ${GLITCHYARD_TOOL_MAP.get(guess)?.title||guess}`:'No suggestion';}
