    function runAction(){runTool();}
    function filterTools(){const query=$dt('[data-dt-search]').value.trim().toLowerCase();root.querySelectorAll('[data-dt-tool]').forEach(button=>{const tool=GLITCHYARD_TOOL_MAP.get(button.dataset.dtTool);button.hidden=Boolean(query&&!`${tool.title} ${tool.description} ${tool.groupTitle}`.toLowerCase().includes(query));});root.querySelectorAll('[data-dt-group]').forEach(group=>{const visible=[...group.querySelectorAll('[data-dt-tool]')].some(b=>!b.hidden);group.hidden=!visible;});}
    const clickHandler=event=>{const t=event.target.closest('button');if(!t)return;if(t.dataset.dtTool){renderTool(t.dataset.dtTool);return;}if(t.matches('[data-dt-run]'))runAction();else if(t.matches('[data-dt-clear]')){input.value='';secondary.value='';selectedFile=null;$dt('[data-dt-file]').value='';setResult('','Cleared');setStatus('Ready');updateCounts();smartSuggestion();}else if(t.matches('[data-dt-swap]')){const a=input.value;input.value=secondary.value;secondary.value=a;updateCounts();smartSuggestion();}else if(t.matches('[data-dt-suggest]')){if(detected)renderTool(detected);}else if(t.matches('[data-dt-copy]')){const text=resultText;if(!text){notify('There is no text result to copy.');return;}copyText(text).then(()=>notify('Result copied.')).catch(()=>notify('Clipboard access is unavailable.'));}else if(t.matches('[data-dt-download]')){if(!resultBlob){notify('Run a tool before downloading its result.');return;}downloadResult(resultBlob,lastBlobName);}else if(t.matches('[data-dt-result-wrap]')){diffWrap=!diffWrap;output.classList.toggle('wrap-lines',diffWrap);t.setAttribute('aria-pressed',String(diffWrap));}};
    function downloadResult(blob,name){try{const url=URL.createObjectURL(blob),a=document.createElement('a');downloadUrls.add(url);a.href=url;a.download=name;a.rel='noopener';a.hidden=true;root.appendChild(a);a.click();a.remove();const release=()=>{if(!downloadUrls.delete(url))return;try{URL.revokeObjectURL(url);}catch(_){}};setTimeout(release,15000);if(api.registerCleanup)api.registerCleanup(release,'glitchyard-download-url');notify(`Prepared ${name} for download.`);}catch(error){notify(`Download unavailable: ${error.message||error}`);}}
